rowdata.pyStepsJavaSource:
Database db_inf = tools.getDatabase();
String strClass = null;
boolean bDecode = false,
        bXML = false;

ClipboardPage page_Attachment = null,
              page_EmbedAttachment = null,
              page_AttachmentPage = tools.findPage("AttachmentPage"),
              page_OpenAttachments = tools.findPage("AttachmentLinksOpened");
ClipboardProperty prop_pxResults = page_OpenAttachments.getProperty("pxResults"),
                  prop_pyAttachment = null;

try {

   page_Attachment = db_inf.open(myStepPage.getString(".pxLinkedRefTo"),true);

   if ( page_Attachment != null ) {
      prop_pxResults.add(page_Attachment);

      strClass = page_Attachment.getString("pxObjClass");

      prop_pyAttachment = page_AttachmentPage.getProperty(".pyAttachments(<append>)");
      page_EmbedAttachment = prop_pyAttachment.getPageValue();


      if ( strClass.equals("Data-WorkAttach-File") ) {
         bDecode= true;
         bXML=false;

        String strfilename = null, 
        	   strFileData = null;
        strfilename = page_Attachment.getString(".pxAttachName");
        strfilename =  (new java.io.File(strfilename)).getName();

		String storageType = myStepPage.getString("pxStorageType");
        oLog.debug("Attachment has storage type of %s", storageType);

        if ( storageType.equalsIgnoreCase("WebStorage") )
        {
          	oLog.debug("Attempting to get attachment content stored in WebStorage...");
          	tools.getParameterPage().putString("fileName", myStepPage.getString("pyMemo"));
          	//greez BUG-268895 use utility function for generalized WebStorage download
        	strFileData = pega_processengine_workutilities.pxGetWebStorageContent(prop_pxResults.getPageValue(prop_pyAttachment.indexOf()));
        }
        else
        {
      		//purip BUG-122627 use the new utility function to get hold of cmis attachment content
  			strFileData = pega_processengine_workutilities.pxGetFileAttachmentContent(prop_pxResults.getPageValue(prop_pyAttachment.indexOf()));
        }

       //Bug-204903 Decoding the file name before putting on the page
        String decodedFileName = StringUtils.decodeCrossOSString(strfilename);
                            page_EmbedAttachment.putString(".pyReference", "");
                            page_EmbedAttachment.putString(".pyData", strFileData);
                            page_EmbedAttachment.putString(".pyName",decodedFileName);
            	         page_EmbedAttachment.putString(".pyDecode","true"); 
           	         page_EmbedAttachment.putString(".pyRemoveXML","false");          	

      } else if ( strClass.equals("Data-WorkAttach-Note") ) {
        page_EmbedAttachment.putString(".pyReference","AttachmentLinksOpened.pxResults("+prop_pyAttachment.indexOf() +").pyNote");
        page_EmbedAttachment.putString(".pyName",page_Attachment.getString(".pyLabel"));
        page_EmbedAttachment.putString(".pyType","txt");
           	        page_EmbedAttachment.putString(".pyDecode","false");
           	        page_EmbedAttachment.putString(".pyRemoveXML","false");          	
      } else if ( strClass.equals("Data-WorkAttach-ScanDocument") ) {
         bDecode= true;
         bXML=true;
        page_EmbedAttachment.putString(".pyReference","AttachmentLinksOpened.pxResults("+prop_pyAttachment.indexOf() +").pyEncodedTIFDocument");
        page_EmbedAttachment.putString(".pyName","tifimage_"+prop_pyAttachment.indexOf()+".tif");
           	        page_EmbedAttachment.putString(".pyDecode","true");
           	        page_EmbedAttachment.putString(".pyRemoveXML","true");          			

      } else if ( strClass.equals("Data-WorkAttach-ScreenShot") ) {
         bDecode= true;
         bXML=true;
        page_EmbedAttachment.putString(".pyReference","AttachmentLinksOpened.pxResults("+prop_pyAttachment.indexOf() +").pyEncodedScreenShot");
                        page_EmbedAttachment.putString(".pyName","Screenshot_"+prop_pyAttachment.indexOf()); 
                        page_EmbedAttachment.putString(".pyType","jpg");		             
           	        page_EmbedAttachment.putString(".pyDecode","true");
           	        page_EmbedAttachment.putString(".pyRemoveXML","true");          	

      } else if ( strClass.equals("Data-WorkAttach-URL") ) {

       String strURL = page_Attachment.getString(".pyURL");

       if ( strURL.startsWith("{"))
       {
            int i = strURL .indexOf(':');
	   strURL = "http"+strURL.substring(i,strURL.length());
       }
       else if ( ! strURL.startsWith("http"))
            strURL = "http://"+strURL ;

       ClipboardPage  cp = tools.findPage("AttachmentLinksOpened.pxResults("+prop_pyAttachment.indexOf()+")");
       cp.getProperty("pyURL").setValue(strURL);

        page_EmbedAttachment.putString(".pyReference","AttachmentLinksOpened.pxResults("+prop_pyAttachment.indexOf() +").pyURL");
        page_EmbedAttachment.putString(".pyName",strURL);		             
           	        page_EmbedAttachment.putString(".pyDecode","false");
        page_EmbedAttachment.putString(".pyType","URL");	
           	        page_EmbedAttachment.putString(".pyRemoveXML","false");          		             
      } 

   }

} catch (DatabaseException dbe) {

  tools.getPrimaryPage().addMessage( dbe.getMessage() );

}
